('event_id', $survey->event_id) === (string) $event->id)>{{ $event->title }}</option>@endforeach</select></div><div class="col-12"><label class="form-label fw-semibold">Questions</label><div id="surveyQuestions">@foreach ($survey->questions as $index => $question)<div class="input-group mb-2"><span class="input-group-text">{{ $index + 1 }}</span><input name="questions[]" class="form-control" value="{{ old('questions.' . $index, $question) }}" required></div>@endforeach</div><button type="button" id="addSurveyQuestion" class="btn btn-outline-success btn-sm"><i class="bi bi-plus-circle me-1"></i>Add question</button></div><div class="col-12"><div class="form-check"><input class="form-check-input" type="checkbox" name="suggestion_enabled" value="1" id="suggestionEnabled" @checked(old('suggestion_enabled', $survey->suggestion_enabled))><label class="form-check-label" for="suggestionEnabled">Include an optional suggestion box</label></div></div></div><button class="btn btn-yg mt-4"><i class="bi bi-check-circle me-1"></i>Save changes</button></form></div></div></div></div>
