<script>
(() => { const audience = document.getElementById('surveyAudience'); const eventWrap = document.getElementById('surveyEventWrap'); const event = document.getElementById('surveyEvent'); const questions = document.getElementById('surveyQuestions'); const add = document.getElementById('addSurveyQuestion'); const sync = () => { const active = audience.value === 'event_attendees'; eventWrap.hidden = !active; event.required = active; }; audience.addEventListener('change', sync); sync(); add.addEventListener('click', () => { const count = questions.children.length + 1; const group = document.createElement('div'); group.className = 'input-group mb-2'; group.innerHTML = `<span class="input-group-text">${count}</span><input name="questions[]" class="form-control" placeholder="Add a question" required>`; questions.append(group); }); })();
</script>
